{"implementation": "import heapq

def solve(case):
    nodes = case.get('nodes')
    utility_threshold = case.get('utility_threshold')
    if nodes is None or utility_threshold is None:
        raise ValueError("Missing required fields: nodes or utility_threshold")
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")

    node_map = {}
    children = {}
    for node in nodes:
        nid = node.get('id')
        parent = node.get('parent')
        depth = node.get('depth')
        removable = node.get('removable')
        utility = node.get('utility')
        if nid is None or depth is None or removable is None or utility is None:
            raise ValueError("Node missing required fields")
        node_map[nid] = node
        children.setdefault(nid, [])
        if parent is not None:
            children.setdefault(parent, []).append(nid)

    retained = set(node_map.keys())

    # Initialize priority queue: (-depth, id) for max depth, then alphabetical id
    heap = []
    for nid, node in node_map.items():
        heapq.heappush(heap, (-node['depth'], nid))

    visit_order = []
    while heap:
        neg_depth, nid = heapq.heappop(heap)
        visit_order.append(nid)
        if nid not in retained:
            continue
        node = node_map[nid]
        # Check if leaf (no retained children)
        child_ids = children.get(nid, [])
        is_leaf = all(cid not in retained for cid in child_ids)
        if is_leaf and node['removable'] and node['utility'] <= utility_threshold:
            retained.discard(nid)
            parent_id = node.get('parent')
            if parent_id is not None and parent_id in retained:
                parent_node = node_map[parent_id]
                heapq.heappush(heap, (-parent_node['depth'], parent_id))

    # Prepare output: retained_node_ids (any order, use sorted for determinism)
    retained_node_ids = sorted(retained)
    return {
        'retained_node_ids': retained_node_ids,
        'visit_order': visit_order
    }
